(() => {
  'use strict';
  const root = document.documentElement;
  if (root.dataset.ksApprovedQaFix === '20261027-v1') return;
  const app = document.getElementById('app');
  const loader = document.getElementById('kland-loading');
  // These are the existing map's lexical visit Set and persistence function.
  if (!app || !loader || typeof visited === 'undefined' || typeof persist !== 'function') {
    root.dataset.ksApprovedQaFix = 'incompatible-source';
    return;
  }

  // Record only successful game openings, without re-rendering/removing the
  // opener while the game owns focus or changing any gameplay behavior.
  let burgerWasOpen = false, newlyVisited = false;
  function recordBurgerVisit() {
    const open = !!document.getElementById('nb-game');
    if (open && !visited.has('nuttin-burger')) {
      visited.add('nuttin-burger');
      persist();
      newlyVisited = true;
      for (const landmark of document.querySelectorAll('.landmark-sprite[data-place-id="nuttin-burger"]')) {
        landmark.classList.add('visited');
      }
      root.dataset.ksBurgerVisitFix = 'recorded';
    }
    if (!open && burgerWasOpen && newlyVisited) {
      // A first visit can originate on the map while the Visited list is open.
      // Refresh that list on close only; All/Open directory openers stay intact.
      const filter = document.querySelector('#panel-places .filters button.active');
      if (filter?.dataset.filter === 'visited' && typeof renderPlaces === 'function') renderPlaces('visited');
      newlyVisited = false;
    }
    burgerWasOpen = open;
  }
  const visitObserver = new MutationObserver(recordBurgerVisit);
  visitObserver.observe(document.body, { childList: true });
  recordBurgerVisit();

  // A restored place may open before the entry screen is dismissed. Inert on
  // the whole app prevents later panel sync from re-enabling hidden controls.
  const originalInert = app.inert;
  const originalAriaHidden = app.getAttribute('aria-hidden');
  let gated = false;
  function entryButtons() {
    return [...loader.querySelectorAll('button:not([disabled])')].filter(button => button.getClientRects().length);
  }
  function focusEntry(last = false) {
    if (loader.hidden) return;
    const buttons = entryButtons();
    const target = buttons[last ? buttons.length - 1 : 0] || loader;
    if (target === loader) loader.tabIndex = -1;
    target.focus({ preventScroll: true });
  }
  function syncGate() {
    if (!loader.hidden) {
      gated = true;
      app.inert = true;
      app.setAttribute('aria-hidden', 'true');
      loader.setAttribute('role', 'dialog');
      loader.setAttribute('aria-modal', 'true');
      if (!loader.contains(document.activeElement) || (document.activeElement === loader && entryButtons().length)) {
        focusEntry();
      }
      return;
    }
    if (!gated) return;
    gated = false;
    app.inert = originalInert;
    if (originalAriaHidden === null) app.removeAttribute('aria-hidden');
    else app.setAttribute('aria-hidden', originalAriaHidden);
    loader.removeAttribute('aria-modal');
    const target = app.querySelector('.panel.open h2') || app.querySelector('.nav button');
    if (target && !target.closest('[inert]')) {
      if (target.tagName === 'H2') target.tabIndex = -1;
      target.focus({ preventScroll: true });
    }
  }
  document.addEventListener('focusin', event => {
    if (!loader.hidden && !loader.contains(event.target)) focusEntry();
  }, true);
  document.addEventListener('keydown', event => {
    if (loader.hidden || event.key !== 'Tab') return;
    const buttons = entryButtons();
    const index = buttons.indexOf(document.activeElement);
    if (!buttons.length || index < 0 || (event.shiftKey && index === 0) || (!event.shiftKey && index === buttons.length - 1)) {
      event.preventDefault();
      event.stopPropagation();
      focusEntry(event.shiftKey);
    }
  }, true);
  new MutationObserver(syncGate).observe(loader, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ['hidden']
  });
  syncGate();
  root.dataset.ksApprovedQaFix = '20261027-v1';
})();
